/**
 * จัดฟอร์แมตข้อมูลสัญลักษณ์ 1909 สำหรับแทรกใน prompt ของ AI
 */
export function formatCardLoreForPrompt(cardId: string): string {
  const lore = CARD_VISUAL_LORE[cardId];
  if (!lore) return "";
  return `  • สัญลักษณ์ภาพ 1909: ${lore.scene1909}
  • จุดสังเกตสำคัญ: ${lore.symbols.join(" · ")}
  • จิตวิทยาเชิงลึก: ต้นแบบ (Archetype) = ${lore.archetype} | เงามืด (Shadow) = ${lore.shadow}
  • คำถามชวนคิดทรงพลัง: "${lore.powerQuestion}"`;
}
